function e(e){let t=e.consecutive_failures??0,n=e.failure_threshold??1;if(e.status===`up`&&t>0&&t<n)return`Confirming ${t}/${n}…`}function t(e){let t=e.consecutive_successes??0;if(!(e.status!==`down`||t<=0))return`recovering ${t}/${e.recovery_threshold??1}`}function n(e){if(!t(e))return;let n=e.consecutive_successes??0,r=e.recovery_threshold??1;return n>=r?`${n} consecutive successful checks; the threshold was lowered to ${r} during the run, so the next successful check confirms the recovery. As of page load.`:`${n} of ${r} consecutive successful checks. The monitor stays down until ${r} in a row succeed. As of page load.`}function r(e){if(e<60)return`${e} s`;let t=Math.floor(e/3600),n=Math.floor(e%3600/60),r=e%60;return[t&&`${t} h`,n&&`${n} min`,r&&`${r} s`].filter(Boolean).join(` `)}function i(e,t){let n=t-1,i=e*n;if(!(n<1||i<600))return`Recovery will be announced about ${r(i)} after the first successful check (${n} more check${n===1?``:`s`} × ${r(e)}). Checks are not sped up during recovery.`}function a(e,t){return(e?.length??0)>0&&t>1}function o(e){return e!==`push`&&e!==`composite`}export{n as a,t as i,a as n,i as o,o as r,e as t};